WITH filtered_store_sales AS (SELECT * FROM store_sales WHERE revenue > 1800), store_sales_stats AS (SELECT YEAR(sale_date) AS sale_year, CASE WHEN revenue >= 3300 THEN 'high' WHEN revenue >= 1900 THEN 'mid' ELSE 'low' END AS revenue_bucket, SUM(units) AS total_units FROM filtered_store_sales GROUP BY YEAR(sale_date), CASE WHEN revenue >= 3300 THEN 'high' WHEN revenue >= 1900 THEN 'mid' ELSE 'low' END) SELECT sale_year, total_units FROM store_sales_stats WHERE total_units > 120;
